<?php
/** Apply the prepared extraction once, preserving all public content and backing up the database. */
if(PHP_SAPI!=='cli'||!in_array('--apply',$argv,true))exit("Usage: php tools/modx/apply-template-refactor.php --apply\n");
$root=dirname(__DIR__,2).'/';if(is_file($root.'cms/template-registry.json'))throw new RuntimeException('Refactor already applied; do not rerun the initial extraction');
$plan=json_decode(file_get_contents($root.'.tmp-refactor-plan.json'),true,512,JSON_THROW_ON_ERROR);define('MODX_API_MODE',true);require $root.'public/index.php';$modx->initialize('mgr');
use MODX\Revolution\{modCategory,modTemplate,modResource,modTemplateVar,modTemplateVarResource,modTemplateVarTemplate,modChunk,modSnippet,modSystemSetting};
$backup=[];foreach([modCategory::class,modTemplate::class,modResource::class,modTemplateVar::class,modTemplateVarResource::class,modTemplateVarTemplate::class,modChunk::class,modSnippet::class] as $class)foreach($modx->getCollection($class) as $o)$backup[$class][]=$o->toArray();file_put_contents($root.'cms/backups/before-template-refactor-'.date('Ymd-His').'.json',json_encode($backup,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT));
$groups=[];function category($modx,&$groups,$name){if(!isset($groups[$name])){$c=$modx->getObject(modCategory::class,['category'=>$name]);if(!$c){$c=$modx->newObject(modCategory::class);$c->set('category',$name);if(!$c->save())throw new RuntimeException('Category failed');}$groups[$name]=(int)$c->get('id');}return $groups[$name];}
foreach($plan['chunks'] as $name=>$html){$o=$modx->getObject(modChunk::class,['name'=>$name]);if(!$o)$o=$modx->newObject(modChunk::class);$o->fromArray(['name'=>$name,'category'=>category($modx,$groups,'Общие'),'description'=>'Общая часть сайта. Контакты берутся из ClientConfig.','snippet'=>$html,'static'=>0]);if(!$o->save())throw new RuntimeException('Chunk failed: '.$name);}
$ids=[];foreach($plan['tvs'] as $rank=>$definition){$name=$definition['name'];$tv=$modx->getObject(modTemplateVar::class,['name'=>$name]);if(!$tv)$tv=$modx->newObject(modTemplateVar::class);$data=['name'=>$name,'caption'=>$definition['caption'],'description'=>$definition['description'],'category'=>category($modx,$groups,$definition['category']),'type'=>$definition['type'],'default_text'=>'','rank'=>$rank,'display'=>'default'];if($definition['type']==='migx')$data['input_properties']=['formtabs'=>json_encode([['caption'=>'Квалификация','fields'=>[['field'=>'label','caption'=>'Название','inputTVtype'=>'text'],['field'=>'value','caption'=>'Описание','inputTVtype'=>'text']]]],JSON_UNESCAPED_UNICODE),'columns'=>json_encode([['header'=>'Название','dataIndex'=>'label','width'=>200],['header'=>'Описание','dataIndex'=>'value','width'=>400]],JSON_UNESCAPED_UNICODE),'btntext'=>'Добавить квалификацию'];$tv->fromArray($data);if(!$tv->save())throw new RuntimeException('TV failed: '.$name);$ids[$name]=(int)$tv->get('id');}
foreach($plan['resource_templates'] as $rid=>$tid){$r=$modx->getObject(modResource::class,(int)$rid);$r->set('template',$tid);if(isset($plan['contents'][(string)$rid]))$r->set('content',$plan['contents'][(string)$rid]);if(!$r->save())throw new RuntimeException('Resource failed');}
foreach($plan['values'] as $rid=>$values){foreach($values as $name=>$value){$criteria=['tmplvarid'=>$ids[$name],'contentid'=>(int)$rid];$o=$modx->getObject(modTemplateVarResource::class,$criteria);if(!$o){$o=$modx->newObject(modTemplateVarResource::class);$o->fromArray($criteria,'',true,true);}$o->set('value',$value);if(!$o->save())throw new RuntimeException('TV value failed');$tid=$plan['resource_templates'][(string)$rid];$criteria=['tmplvarid'=>$ids[$name],'templateid'=>$tid];if(!$modx->getObject(modTemplateVarTemplate::class,$criteria)){$link=$modx->newObject(modTemplateVarTemplate::class);$link->fromArray($criteria+['rank'=>array_search($name,array_keys($ids),true)],'',true,true);$link->save();}}}
$registry=[];foreach($plan['templates'] as $row){$t=$modx->getObject(modTemplate::class,(int)$row['id']);$t->fromArray(['templatename'=>$row['templatename'],'description'=>$row['description'],'category'=>0,'content'=>$row['content'],'static'=>0]);if(!$t->save())throw new RuntimeException('Template failed');$registry[]=['id'=>(int)$row['id'],'name'=>$row['templatename']];}
// All page types keep the SEO controls, including newly added resources of these templates.
foreach($registry as $t)foreach(['seo_title','seo_description','seo_image','seo_index'] as $name){$tv=$modx->getObject(modTemplateVar::class,['name'=>$name]);$criteria=['templateid'=>$t['id'],'tmplvarid'=>$tv->get('id')];if(!$modx->getObject(modTemplateVarTemplate::class,$criteria)){$link=$modx->newObject(modTemplateVarTemplate::class);$link->fromArray($criteria,'',true,true);$link->save();}}
foreach($plan['remove_templates'] as $tid){if($modx->getCount(modResource::class,['template'=>$tid]))throw new RuntimeException('Template still in use');$t=$modx->getObject(modTemplate::class,$tid);if($t)$t->remove();}
$unused=$modx->getObject(modTemplate::class,1);if($unused&&!$modx->getCount(modResource::class,['template'=>1]))$unused->remove();
$old=$modx->getObject(modCategory::class,['category'=>'ZUBR GYM · HTML']);if($old){if($modx->getCount(modTemplate::class,['category'=>$old->get('id')]))throw new RuntimeException('Old category still in use');$old->remove();}
$prefix="require_once MODX_BASE_PATH . '../cms/elements/ContentElements.php';\n\$elements = new \\Zubr\\Site\\ContentElements(\$modx);\n";
foreach(['Breadcrumbs'=>'breadcrumbs','ContentContents'=>'contents','RelatedArticles'=>'related','RepeatItems'=>'repeat'] as $name=>$method){$s=$modx->getObject(modSnippet::class,['name'=>$name]);if(!$s)$s=$modx->newObject(modSnippet::class);$s->fromArray(['name'=>$name,'category'=>category($modx,$groups,'Общие'),'description'=>'Повторяемый контент и навигация. Источник: cms/elements/ContentElements.php.','snippet'=>$prefix.'return $elements->'.$method.'('.($method==='repeat'?'$scriptProperties':'').');']);if(!$s->save())throw new RuntimeException('Snippet failed');}
file_put_contents($root.'cms/template-registry.json',json_encode(['phase'=>'chunks-and-tvs','templates'=>$registry,'chunks'=>array_keys($plan['chunks']),'fields'=>$ids],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));
// Update the mapping used by checks and later exports; source HTML remains a static preview.
$file=$root.'cms/import-result.json';$report=json_decode(file_get_contents($file),true);$report['mode']='chunks-and-tvs';foreach($report['resources'] as &$r)if(isset($plan['resource_templates'][(string)$r['id']]))$r['template']=$plan['resource_templates'][(string)$r['id']];unset($r);file_put_contents($file,json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));
// Snapshot the editable elements outside public; these files are an export, not an automatic importer.
@mkdir($root.'cms/chunks',0777,true);@mkdir($root.'cms/templates/structured',0777,true);foreach($plan['chunks'] as $name=>$html)file_put_contents($root.'cms/chunks/'.$name.'.html',$html);foreach($plan['templates'] as $t)file_put_contents($root.'cms/templates/structured/'.$t['id'].'.html',$t['content']);
$modx->cacheManager->refresh();echo count($registry).' templates, '.count($plan['chunks']).' chunks, '.count($ids)." TV fields; old category removed.\n";
